#!/bin/sh
# Download and run the installer generated by MyGo for the latest release.
# It detects macOS/Linux and CPU architecture and verifies the archive's
# Ed25519 signature before installing. No root privileges are needed.
#
# curl -fsSL https://raw.githubusercontent.com/markbang/cohub-mygo/main/install.sh | sh
# curl -fsSL https://raw.githubusercontent.com/markbang/cohub-mygo/main/install.sh | sh -s -- --uninstall
# COHUB_MYGO_VERSION=0.0.1 sh install.sh
set -eu

version="${COHUB_MYGO_VERSION:-latest}"
case "$version" in
  latest) base='https://github.com/markbang/cohub-mygo/releases/latest/download' ;;
  *)
    version="${version#v}"
    case "$version" in
      ''|*[!0-9A-Za-z.+-]*)
        echo 'install.sh: invalid COHUB_MYGO_VERSION' >&2
        exit 2
        ;;
    esac
    base="https://github.com/markbang/cohub-mygo/releases/download/v$version"
    # Keep a pinned version's manifest as well as its installer pinned.
    export COHUB_MYGO_DOWNLOAD_URL="$base"
    ;;
esac

work="$(mktemp -d)"
trap 'rm -rf "$work"' 0
trap 'exit 1' HUP INT TERM
curl -fSL --retry 3 "$base/install.sh" -o "$work/install.sh"
sh "$work/install.sh" "$@"
